window.runRoomToolsTests=async()=>{
 const steps=[],el=id=>document.getElementById(id),click=id=>el(id).click(),set=(id,v)=>el(id).value=v;
 const check=(ok,label)=>{if(!ok)throw Error(label);steps.push(label);};
 const wait=ms=>new Promise(r=>setTimeout(r,ms)),until=async(fn,label)=>{for(let i=0;i<300;i++){if(await fn())return;await wait(20);}throw Error(label);};
 const visible=id=>getComputedStyle(el(id)).display!=='none';
 async function login(email){click('loginTab');set('authEmail',email);set('authPassword','DemoPass123!');const n=el('botQuestion').textContent.match(/(\d+) \+ (\d+)/);set('botAnswer',Number(n[1])+Number(n[2]));el('notRobot').checked=true;el('authForm').requestSubmit();await until(()=>authenticated(),'Cannot sign in during room tools tests');await loadRoommateData();}
 const me=currentUser.id;
 openRoom('1');check(visible('roomPanelOverview')&&!visible('roomPanelChecks')&&!visible('roomPanelOwner'),'Detail starts with one compact panel');
 click('roomTabChecks');check(visible('roomPanelChecks')&&!visible('roomPanelOverview')&&el('verificationPage').textContent.includes('3/3'),'Verification and reviews tab contains existing content');
 click('roomTabOwner');check(visible('roomPanelOwner')&&el('contactLandlord').textContent.includes('Nguyễn Thị Hằng'),'Owner tab shows correct profile');
 click('roomTabOverview');check(el('costExtra').classList.contains('hidden')&&el('costExtra').querySelectorAll('.cost-row').length===5,'Cost breakdown starts collapsed');click('costDetails');check(!el('costExtra').classList.contains('hidden'),'Cost details remain accessible');click('costDetails');
 check([...document.querySelectorAll('#slotListingForm>.tool-group')].map(n=>n.open).join(',')==='true,false,false','Posting form has three groups and only first expanded');
 check(el('rfCampus').closest('.roommate-advanced-grid')&&el('rfVacancies').closest('.roommate-advanced-grid'),'Advanced filters contain secondary criteria');
 for(const [index,r] of rooms.entries())check(RoomTools.score('rental',r)===[92,88,75,35,55,30][index],'Rental score fixture '+r.id);
 for(const [index,r] of sampleRoommateListings.entries())check(RoomTools.score('shared',r)===[92,88,75,72,55,35][index],'Shared score fixture '+r.id);
 const own=roommateSlots.find(r=>!r.is_sample);check(RoomTools.score('shared',own)===null&&RoomTools.trust('shared',own).includes('Chưa chấm điểm'),'User listing has no invented trust score');
 document.querySelector('#detailRoomTools .trust-score').click();check(el('trustDialog').open&&el('trustDialogBody').textContent.includes('chưa có công thức')&&el('trustDialogBody').textContent.includes('92/100'),'Score dialog explains simulated methodology');RoomTools.close('trustDialog');
 RoomTools.clearSelection();showPage('search');set('minPrice','0');set('maxPrice','20000000');renderSearch();
 document.querySelector('#roomResults [data-compare-id="1"]').click();check(RoomTools.selection.length===1&&visible('comparisonBar')&&el('openComparison').disabled,'First pick shows compact comparison bar');
 document.querySelector('#roomResults [data-compare-id="1"]').click();check(RoomTools.selection.length===0&&!visible('comparisonBar'),'Picking selected card again removes selection');RoomTools.toggleCompare('rental','1');
 document.querySelector('#roomResults [data-compare-id="2"]').click();check(RoomTools.selection.length===2&&!el('openComparison').disabled,'Second pick enables comparison');
 RoomTools.toggleCompare('rental','3');RoomTools.toggleCompare('rental','5');check(RoomTools.selection.length===3&&!RoomTools.selection.some(s=>s.id==='5'),'Fourth room blocked');
 RoomTools.toggleCompare('rental','6');check(!RoomTools.selection.some(s=>s.id==='6'),'Zero-layer rental cannot be selected');
 window.scrollTo({top:300,behavior:'instant'});const y=scrollY;click('openComparison');check(!el('comparisonPage').classList.contains('hidden')&&el('comparisonContent').querySelectorAll('thead th').length===4,'Comparison displays three room columns');
 check(el('comparisonContent').textContent.includes('92')&&el('comparisonContent').textContent.includes('88')&&el('comparisonContent').textContent.includes('75')&&el('comparisonContent').textContent.includes('/ phòng / tháng'),'Rental price units and scores are consistent');
 const scroll=el('comparisonContent').querySelector('.comparison-scroll');check(scroll.clientWidth<=innerWidth&&document.documentElement.scrollWidth<=innerWidth+1,'Comparison table scroll stays inside page');
 check(innerWidth>700||scroll.scrollWidth>scroll.clientWidth,'Mobile table has internal horizontal scrolling');
 click('comparisonEdit');await wait(60);check(!el('searchPage').classList.contains('hidden')&&Math.abs(scrollY-y)<3&&el('minPrice').value==='0','Edit selection restores list scroll and filters');
 RoomTools.openComparison();click('comparisonSave');check(JSON.parse(localStorage.getItem('timtro_compare_saved_v1_'+me)).length===1,'Comparison saved per account');
 document.querySelector('[data-remove-comparison="3"]').click();check(RoomTools.selection.length===2&&el('comparisonContent').querySelectorAll('thead th').length===3,'Removing room updates comparison columns');
 RoomTools.toggleCompare('shared','sample-slot-1');check(el('compareSwitchDialog').open&&RoomTools.selection[0].kind==='rental','Switching price type requires explicit confirmation');
 RoomTools.close('compareSwitchDialog');check(RoomTools.selection.length===2,'Cancel retains old comparison');
 RoomTools.toggleCompare('shared','sample-slot-1');click('switchComparison');check(RoomTools.selection.length===1&&RoomTools.selection[0].kind==='shared','Confirm replaces selection with new kind');
 RoomTools.toggleCompare('shared','sample-slot-2');RoomTools.openComparison();check(el('comparisonContent').textContent.includes('/ người / tháng')&&el('comparisonContent').textContent.includes('Sức chứa')&&el('comparisonContent').textContent.includes('Chưa cung cấp'),'Shared comparison has per-person prices and missing values');
 click('comparisonClear');check(!visible('comparisonBar')&&el('comparisonContent').textContent.includes('Chọn từ 2'),'Clear selection shows empty state');
 click('openSavedComparisons');await wait(20);document.querySelector('[data-load-comparison]').click();await until(()=>RoomTools.selection.length===3,'Saved comparison failed to reopen');check(RoomTools.selection.every(s=>s.kind==='rental'),'Saved set restores original rental choices');
 click('openSavedComparisons');await wait(20);document.querySelector('[data-delete-comparison]').click();check(JSON.parse(localStorage.getItem('timtro_compare_saved_v1_'+me)).length===0&&RoomTools.selection.length===3,'Deleting saved set retains current choices');RoomTools.close('savedComparisonDialog');RoomTools.saveComparison();
 // Reports use actual IndexedDB with actual file bytes, never a fake production adapter.
 openRoom('1');document.querySelector('#detailRoomTools [data-report-kind]').click();check(el('reportDialog').open&&el('reportRoom').textContent===rooms[0].title,'Report is tied to current rental room');
 el('reportForm').requestSubmit();check(!el('reportForm').checkValidity(),'Category and reason required');
 set('reportCategory','Thông tin sai');set('reportReason','Thông tin sai <img src=x onerror=alert(1)>');el('reportForm').requestSubmit();check(el('reportError').textContent.includes('Bổ sung'),'Report requires text or file evidence');
 RoomTools.addFiles([new File(['bad'],'bad.svg',{type:'image/svg+xml'})]);check(el('reportError').textContent.includes('Chỉ nhận')&&!el('reportFileList').children.length,'Unsupported evidence rejected');
 RoomTools.addFiles([new File([new Uint8Array(5*1024*1024+1)],'too-big.png',{type:'image/png'})]);check(el('reportError').textContent.includes('5 MB')&&!el('reportFileList').children.length,'Oversized file rejected');
 const receipt=()=>new File(['%PDF-1.4 local-receipt'],'bien-lai.pdf',{type:'application/pdf'});
 RoomTools.addFiles([receipt(),receipt(),receipt(),receipt()]);check(el('reportFileList').children.length===3&&el('reportError').textContent.includes('3 tệp'),'Three-file limit enforced');
 document.querySelector('[data-remove-evidence="2"]').click();document.querySelector('[data-remove-evidence="1"]').click();check(el('reportFileList').children.length===1&&el('reportFileList').textContent.includes('bien-lai.pdf'),'Evidence can be removed before save');
 el('reportForm').requestSubmit();await until(()=>el('reportSuccess').textContent.includes('chưa gửi quản trị'),'Report failed to save');
 const records=await RoomTools.reportStore('list'),firstId=records[0].id;check(records.length===1&&records[0].userId===me&&await records[0].files[0].blob.text()==='%PDF-1.4 local-receipt','Report and original PDF bytes saved in IndexedDB');
 check(RoomTools.score('rental',rooms[0])===92&&checkCount(rooms[0])===3,'Reporting does not change score or verification');
 click('viewReportHistory');await until(()=>el('reportHistoryList').querySelector('.report-record'),'Report history missing');check(el('reportHistoryList').textContent.includes('<img src=x')&&!el('reportHistoryList').querySelector('img[src="x"]'),'Report text is safely escaped');
 document.querySelector('[data-preview-report]').click();await until(()=>el('evidenceDialog').open,'Saved evidence failed to open');check(el('evidencePreviewBody').querySelector('a[download]').href.startsWith('blob:')&&el('evidencePreviewBody').querySelector('a[target="_blank"]'),'Saved PDF can be opened and downloaded');RoomTools.close('evidenceDialog');
 showPage('roommates');openSlotDetail('sample-slot-2');document.querySelector('#slotDialogBody [data-report-kind]').click();check(el('reportDialog').open&&el('reportRoom').textContent.includes(sampleRoommateListings[1].title),'Shared slot detail opens report for correct post');
 set('reportCategory','Giao tiếp không phù hợp');set('reportReason','Trao đổi không phù hợp');set('reportEvidenceText','Tin nhắn bằng chứng');el('reportForm').requestSubmit();await until(()=>el('reportSuccess').textContent.includes('chưa gửi quản trị'),'Text-evidence report failed');RoomTools.close('reportDialog');rmClose('slotDialog');
 check((await RoomTools.reportStore('list')).length===2,'Text-only evidence is accepted');
 showPage('reportHistory');await until(()=>el('reportHistoryList').children.length===2,'Second history record missing');const textRecord=(await RoomTools.reportStore('list')).find(r=>r.kind==='shared');
 const originalConfirm=window.confirm;window.confirm=()=>true;document.querySelector('[data-delete-report="'+textRecord.id+'"]').click();await until(async()=>(await RoomTools.reportStore('list')).length===1,'Delete did not remove record');window.confirm=originalConfirm;check(true,'Delete removes report and its evidence');
 RoomTools.openReport('rental','2');set('reportCategory','Hình ảnh sai');set('reportReason','Ảnh được dùng làm bằng chứng');const photo=await(await fetch(photos[0])).blob();RoomTools.addFiles([new File([photo],'bang-chung.jpg',{type:'image/jpeg'})]);el('reportForm').requestSubmit();await until(()=>el('reportSuccess').textContent.includes('chưa gửi quản trị'),'Image report failed');RoomTools.close('reportDialog');await RoomTools.renderReports();const imageReport=(await RoomTools.reportStore('list')).find(r=>r.roomId==='2');await RoomTools.previewReport(imageReport.id,0);await until(()=>el('evidencePreviewBody').querySelector('img')?.naturalWidth>0,'Stored photo cannot render');check(true,'Stored image evidence reopens at full resolution');RoomTools.close('evidenceDialog');await RoomTools.reportStore('delete',imageReport.id);
 demoLogout();check(el('reportHistoryList').textContent===''&&el('reportRoom').textContent===''&&!visible('comparisonBar'),'Logout clears report and comparison UI');
 await login('mai.987654321@st.ueh.edu.vn');showPage('reportHistory');await until(()=>el('reportHistoryList').textContent.includes('chưa lưu'),'Second account history not empty');check((await RoomTools.reportStore('list')).length===0,'Reports are isolated by current account');
 await RoomTools.reportStore('delete',firstId);check(RoomTools.selection.length===0&&!localStorage.getItem('timtro_compare_saved_v1_'+currentUser.id),'Second account has no first-account comparison');
 demoLogout();await login('test.123456789@st.ueh.edu.vn');check((await RoomTools.reportStore('list')).length===1,'Other account cannot delete first-account report');check(RoomTools.selection.length===3,'First account comparison selection restored');
 showPage('reportHistory');await RoomTools.renderReports();check(document.documentElement.scrollWidth<=innerWidth+1,'Report history fits mobile and desktop');
 showPage('search');openRoom('2');RoomTools.openComparison();click('comparisonEdit');check(!el('searchPage').classList.contains('hidden'),'Comparison opened from detail returns to its source list');
 openRoom('1');click('roomTabOwner');check(document.documentElement.scrollWidth<=innerWidth+1,'Compact owner panel does not overflow');
 selectRoomTab('overview');if(innerWidth<700){const info=el('detailRoomTools').getBoundingClientRect(),gallery=el('mainGallery').getBoundingClientRect();check(info.top<gallery.top,'Mobile score and report actions appear before photo and long content');check(el('comparisonBar').getBoundingClientRect().height<100,'Mobile comparison bar stays compact');}
 return steps;
};
